"""Individually authored exercises; no scraping or numeric-variant inflation."""
def refs(node):return next(n for n in pack['nodes'] if n['id']==N(node))['lesson']['sourceIds']
def base(key,node,diff,prompt,why,hints,diag=None,extra=()):
 q=dict(id=f'{P}.q.poly-{key}',nodeIds=[N(node),*[N(x) for x in extra]],difficulty=diff,prompt=prompt,explanation=why,hints=list(hints),sourceId='polymer-original',sourceIds=refs(node))
 if diag:q['diagramId']=D('quiz-'+diag) if any(d['id']==D('quiz-'+diag) for d in pack['diagrams']) else D(diag)
 return q
def C(key,node,diff,prompt,answer,wrongs,why,hints,diag=None,extra=(),mis='reasoning'):
 q=base(key,node,diff,prompt,why,hints,diag,extra);q.update(kind='choice',answer='a',choices=[dict(id='a',text=answer,feedback=why)])
 for i,(text,feedback) in enumerate(wrongs):q['choices'].append(dict(id=chr(98+i),text=text,feedback=feedback,misconception='polymer.'+mis))
 pack['questions'].append(q)
def S(key,node,diff,prompt,answer,aliases,why,hints,diag=None,extra=()):
 q=base(key,node,diff,prompt,why,hints,diag,extra);q.update(kind='text',answer=answer,aliases=list(aliases));pack['questions'].append(q)
def Q(key,node,diff,prompt,answer,unit,why,hints,tolerance=0,diag=None,extra=()):
 q=base(key,node,diff,prompt,why,hints,diag,extra);q.update(kind='numeric',answer=answer,tolerance=tolerance)
 if unit:q['unit']=unit
 pack['questions'].append(q)
